<?php
declare(strict_types=1);
require_once __DIR__.'/_response.php';header('Cache-Control: no-store');
if(($_SERVER['REQUEST_METHOD']??'')!=='POST'){header('Allow: POST');sendJsonResponse(['erreur'=>'Méthode non autorisée.'],405);exit;}
try{require_once __DIR__.'/../config/session.php';startSecureSession();$id=$_SESSION['utilisateur_id']??null;if(!is_int($id)||!in_array($_SESSION['role']??null,['employe','administrateur'],true)){sendJsonResponse(['erreur'=>'Accès réservé au personnel.'],403);exit;}$token=$_SERVER['HTTP_X_CSRF_TOKEN']??'';if(!is_string($token)||!isset($_SESSION['csrf_token'])||!hash_equals($_SESSION['csrf_token'],$token)){sendJsonResponse(['erreur'=>'Jeton CSRF invalide.'],403);exit;}$input=json_decode(file_get_contents('php://input')?:'',true,16,JSON_THROW_ON_ERROR);$horaireId=filter_var($input['horaire_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$action=$input['action']??'sauvegarder';require __DIR__.'/../config/database.php';$account=$pdo->prepare('SELECT actif,role FROM utilisateur WHERE utilisateur_id=?');$account->execute([$id]);$staff=$account->fetch(PDO::FETCH_ASSOC);if(!$staff||!(bool)$staff['actif']||!in_array($staff['role'],['employe','administrateur'],true)){sendJsonResponse(['erreur'=>'Accès refusé.'],403);exit;}if($action==='supprimer'){if($horaireId===false||$horaireId===null){sendJsonResponse(['erreur'=>'Horaire invalide.'],422);exit;}$stmt=$pdo->prepare('DELETE FROM horaire WHERE horaire_id=?');$stmt->execute([$horaireId]);sendJsonResponse(['message'=>'Horaire supprimé.']);exit;}$jour=is_string($input['jour']??null)?trim($input['jour']):'';$open=$input['heure_ouverture']??'';$close=$input['heure_fermeture']??'';if($jour===''||strlen($jour)>20||!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/D',$open)||!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/D',$close)||$open>=$close){sendJsonResponse(['erreur'=>'Horaire invalide.'],422);exit;}if($horaireId===false||$horaireId===null){$stmt=$pdo->prepare('INSERT INTO horaire (jour,heure_ouverture,heure_fermeture) VALUES (?,?,?)');$stmt->execute([$jour,$open,$close]);$horaireId=(int)$pdo->lastInsertId();$status=201;}else{$stmt=$pdo->prepare('UPDATE horaire SET jour=?,heure_ouverture=?,heure_fermeture=? WHERE horaire_id=?');$stmt->execute([$jour,$open,$close,$horaireId]);$status=200;}sendJsonResponse(['message'=>'Horaire enregistré.','horaire_id'=>$horaireId],$status);
}catch(JsonException $e){sendJsonResponse(['erreur'=>'JSON invalide.'],400);}catch(Throwable $e){error_log('Échec gestion horaires : '.$e->getMessage());sendJsonResponse(['erreur'=>'Erreur interne.'],500);}
